namespace OCA\Forms\Mcp\Service {class MembershipReached extends \RuntimeException{}class CircleRuntime {public static ?\Closure $after=null;public static bool $inRead=false;public static function assertRecipientMember(string $a,string $c,string $u,string $s):void{self::$inRead=CircleDetached\ShareWriteBoundary::$active;if(self::$after!==null){(self::$after)();return;}throw new MembershipReached();}}}
