require_once dirname(__DIR__,3).'/mcp/vendor/autoload.php';require_once dirname(__DIR__,3).'/mcp/vendor/nextcloud/ocp/OCP/Share/IShare.php';require_once __DIR__.'/../src/Service/CircleNativeShareWrapperService.php';
use OCA\Forms\Mcp\Service\{CircleNativeShareWrapperService,CircleRuntime,MembershipReached,CircleDetached\ShareWriteBoundary};
final class CircleActivationChildReadTest extends \PHPUnit\Framework\TestCase {
 protected function setUp():void{ShareWriteBoundary::$reads=0;ShareWriteBoundary::$active=false;CircleRuntime::$inRead=false;CircleRuntime::$after=null;}
 private function read(bool $cap,bool $grant):void{$w=(new ReflectionClass(CircleNativeShareWrapperService::class))->newInstanceWithoutConstructor();foreach(['assertFresh'=>static fn()=>null,'actorUid'=>'actor','currentRecipient'=>'member','transferCapability'=>$cap?new ShareWriteBoundary():null,'childGrant'=>$grant?['pending'=>true]:null]as$k=>$v)(new ReflectionProperty($w,$k))->setValue($w,$v);$share=$this->createMock(\OCP\Share\IShare::class);$share->method('getId')->willReturn('31');$share->method('getShareType')->willReturn(7);$share->method('getSharedWith')->willReturn('circle');try{$w->getChild($share,new \OCA\Circles\Model\FederatedUser());self::fail('Membership check skipped');}catch(MembershipReached){}self::assertFalse(ShareWriteBoundary::$active);}
 public function testExistingChildReadStillChecksMembershipWithinScope():void{$this->read(true,false);self::assertSame(1,ShareWriteBoundary::$reads);self::assertTrue(CircleRuntime::$inRead);}
 public function testCreationGrantCannotEnterThePureReadScope():void{$this->read(true,true);self::assertSame(0,ShareWriteBoundary::$reads);self::assertFalse(CircleRuntime::$inRead);}
 public function testGrantIntroducedDuringReadStillCannotCreate():void{$w=(new ReflectionClass(CircleNativeShareWrapperService::class))->newInstanceWithoutConstructor();foreach(['assertFresh'=>static fn()=>null,'actorUid'=>'actor','currentRecipient'=>'member','transferCapability'=>new ShareWriteBoundary(),'childGrant'=>null]as$k=>$v)(new ReflectionProperty($w,$k))->setValue($w,$v);CircleRuntime::$after=static function()use($w):void{(new ReflectionProperty($w,'childGrant'))->setValue($w,['pending'=>true]);};$share=$this->createMock(\OCP\Share\IShare::class);$share->method('getId')->willReturn('31');$share->method('getShareType')->willReturn(7);$share->method('getSharedWith')->willReturn('circle');$this->expectException(RuntimeException::class);$this->expectExceptionMessage('Circle child creation cannot enter the pure read');try{$w->getChild($share,new \OCA\Circles\Model\FederatedUser());}finally{self::assertFalse(ShareWriteBoundary::$active);}}
 public function testOrdinaryProviderKeepsItsExistingChecks():void{$this->read(false,false);self::assertSame(0,ShareWriteBoundary::$reads);self::assertFalse(CircleRuntime::$inRead);}
}
